// ─── Card Generation (Finite Projective Plane) ───────────────────────────────
// For order n (prime), generates n²+n+1 cards, each with n+1 symbols.
// Any two cards share exactly one symbol.

function generateDeck(order: number): CardData[] {
  const cards: CardData[] = [];

  cards.push({ symbols: Array.from({ length: order + 1 }, (_, i) => i) });

  for (let i = 0; i < order; i++) {
    const syms = [0];
    for (let j = 0; j < order; j++) {
      syms.push(order + 1 + i * order + j);
    }
    cards.push({ symbols: syms });
  }

  for (let i = 0; i < order; i++) {
    for (let j = 0; j < order; j++) {
      const syms = [i + 1];
      for (let k = 0; k < order; k++) {
        syms.push(order + 1 + k * order + ((i * k + j) % order));
      }
      cards.push({ symbols: syms });
    }
  }

  return cards;
}

function shuffleArray<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

