// ─── Component ────────────────────────────────────────────────────────────────

const CONFETTI_COLORS = ['#f97583', '#d2a8ff', '#79c0ff', '#3fb950', '#f59e0b', '#ff6bcb'];
const CHEERS: (keyof typeof T)[] = ['great', 'amazing', 'perfect', 'super', 'wow', 'fast'];

const STORAGE_KEY = 'atlantis-spotit-best';

function getBest(difficulty: Difficulty): number {
  try {
    const data = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '{}');
    return data[difficulty] ?? 0;
  } catch { return 0; }
}

function saveBest(difficulty: Difficulty, score: number): void {
  try {
    const data = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '{}');
    data[difficulty] = score;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch { /* noop */ }
}

export function SpotIt({ lang, canOnline }: SpotItProps) {
  const [phase, setPhase] = useState<Phase>('theme');
  const [gameMode, setGameMode] = useState<GameMode>('solo');
  const [symbolTheme, setSymbolTheme] = useState<SymbolTheme>('animals');
  const [difficulty, setDifficulty] = useState<Difficulty>('easy');
  const [currentPair, setCurrentPair] = useState<[CardData, CardData] | null>(null);
  const [matchSymbol, setMatchSymbol] = useState<number>(-1);
  const [round, setRound] = useState(0);
  const [score, setScore] = useState(0);
  const [opponentScore, setOpponentScore] = useState(0);
  const [playerScores, setPlayerScores] = useState<Record<string, number>>({});
  const [timer, setTimer] = useState(0);
  const [hintMsg, setHintMsg] = useState('');
  const [wrongId, setWrongId] = useState<string | null>(null);
  const [correctId, setCorrectId] = useState<string | null>(null);
  const [showPoints, setShowPoints] = useState(false);
  const [isNewRecord, setIsNewRecord] = useState(false);
  const [symbolRotations, setSymbolRotations] = useState<Map<string, number>>(new Map());
  const [symbolDelays, setSymbolDelays] = useState<Map<string, number>>(new Map());
  const [shuffledSymbols, setShuffledSymbols] = useState<[number[], number[]]>([[], []]);
  const [opponentLeftMsg, setOpponentLeftMsg] = useState(false);
  const [rematchState, setRematchState] = useState<'none' | 'sent' | 'received'>('none');

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const deckRef = useRef<CardData[]>([]);
  const roundRef = useRef(0);
  const roundResolvedRef = useRef(false);

  const [playerName] = useState(() => loadPlayerName() || (lang === 'pt' ? 'Jogador' : 'Player'));

  const handleMpEvent = useCallback((event: MultiplayerEvent) => {
    switch (event.type) {
      case 'guest-joined':
        mpRef.current.addPlayer({ id: event.playerId, name: event.name, isHost: false });
        mpRef.current.sendEvent({
          type: 'host-ack',
          name: playerName,
          playerId: mpRef.current.room?.playerId ?? '',
          players: mpRef.current.room?.players ?? [],
        });
        break;
      case 'host-ack':
        mpRef.current.setConnected(event.name);
        if (event.players) mpRef.current.setPlayers([...event.players, { id: mpRef.current.room?.playerId ?? '', name: playerName, isHost: false }]);
        break;
      case 'player-list':
        mpRef.current.setPlayers(event.players);
        break;
      case 'game-state': {
        const p = event.payload as Record<string, unknown>;
        if (p.action === 'guest-spot') {
          // Host receives guest's correct tap — resolve if not already resolved
          if (roundResolvedRef.current) return;
          roundResolvedRef.current = true;
          const guestTimer = p.timer as number;
          const timeBonus = Math.ceil(guestTimer * 2);
          const pts = 100 + timeBonus;
          const guestId = p.playerId as string;
          setOpponentScore((prev) => prev + pts);
          setPlayerScores((prev) => ({ ...prev, [guestId]: (prev[guestId] ?? 0) + pts }));
          const cId = `${p.cardIndex}-${p.symbolIndex}`;
          setCorrectId(cId);
          setShowPoints(false);
          setHintMsg(t('theyScored', lang));
          setPhase('correct');
          mpRef.current.sendEvent({
            type: 'game-state',
            payload: { action: 'round-result', winnerId: guestId, winnerName: '', points: pts, correctId: cId },
          });
          setTimeout(() => { nextRoundRef.current(); }, 900);
        } else if (p.action === 'start-round') {
          // Guest receives card pair from host
          const pair = p.pair as [CardData, CardData];
          const r = p.round as number;
          const matchSym = p.matchSymbol as number;
          const totalRounds = p.totalRounds as number;
          const timePerRound = p.timePerRound as number;
          setCurrentPair(pair);
          setMatchSymbol(matchSym);
          setRound(r);
          roundRef.current = r - 1;
          setTimer(timePerRound);
          setWrongId(null);
          setCorrectId(null);
          setHintMsg('');
          setShowPoints(false);
          roundResolvedRef.current = false;
          setPhase('playing');
          // Store totalRounds for display
          (configRef as React.MutableRefObject<{ totalRounds: number; timePerRound: number }>).current = { totalRounds, timePerRound };
        } else if (p.action === 'round-result') {
          roundResolvedRef.current = true;
          const winnerId = p.winnerId as string;
          const myId = mpRef.current.room?.playerId;
          const iWon = winnerId === myId;
          const pts = p.points as number;
          // Update per-player scores
          setPlayerScores((prev) => ({ ...prev, [winnerId]: (prev[winnerId] ?? 0) + pts }));
          if (iWon) {
            setScore((prev) => prev + pts);
            setHintMsg(t('youScored', lang));
          } else {
            setOpponentScore((prev) => prev + pts);
            setHintMsg(t('theyScored', lang));
          }
          setCorrectId(p.correctId as string);
          setShowPoints(iWon);
          setPhase('correct');
        } else if (p.action === 'game-over-scores') {
          setScore(p.myScore as number ?? score);
          setOpponentScore(p.opponentScore as number ?? opponentScore);
          setPhase('gameover');
        }
        break;
      }
      case 'game-over':
        setPhase('gameover');
        break;
      case 'rematch-request':
        setRematchState('received');
        break;
      case 'rematch-accepted':
        setRematchState('none');
        setScore(0);
        setOpponentScore(0);
        setPhase('menu');
        break;
      case 'player-left':
        setOpponentLeftMsg(true);
        setPhase('gameover');
        break;
    }
  }, [playerName, lang]);

  const mpHook = useMultiplayer({ gameId: 'spotit', playerName, onEvent: handleMpEvent });
  const mpRef = useRef(mpHook);
  mpRef.current = mpHook;
  const browser = useRoomBrowser({ gameId: 'spotit', enabled: gameMode === 'online' });
  const configRef = useRef({ totalRounds: 10, timePerRound: 15 });
  const nextRoundRef = useRef<() => void>(() => {});

  const config = DIFFICULTY[difficulty];
  const activeSymbols = useMemo(() => getSymbols(symbolTheme), [symbolTheme]);

  const generateSymbolStyles = useCallback((pair: [CardData, CardData]) => {
    const rots = new Map<string, number>();
    const delays = new Map<string, number>();
    const shuffled: [number[], number[]] = [shuffleArray(pair[0].symbols), shuffleArray(pair[1].symbols)];
    pair.forEach((_, ci) => {
      shuffled[ci].forEach((sym, si) => {
        const key = `${ci}-${sym}`;
        rots.set(key, Math.floor(Math.random() * 40 - 20));
        delays.set(key, si * 0.05);
      });
    });
    setSymbolRotations(rots);
    setSymbolDelays(delays);
    setShuffledSymbols(shuffled);
  }, []);

  const startGame = useCallback((diff: Difficulty) => {
    setDifficulty(diff);
    const cfg = DIFFICULTY[diff];
    configRef.current = { totalRounds: cfg.totalRounds, timePerRound: cfg.timePerRound };
    const rawDeck = generateDeck(cfg.order);
    const shuffled = shuffleArray(rawDeck);
    deckRef.current = shuffled;
    roundRef.current = 0;
    roundResolvedRef.current = false;

    setRound(1);
    setScore(0);
    setOpponentScore(0);
    setPlayerScores({});
    setHintMsg('');
    setWrongId(null);
    setCorrectId(null);
    setIsNewRecord(false);

    const pair: [CardData, CardData] = [shuffled[0], shuffled[1]];
    setCurrentPair(pair);
    const match = pair[0].symbols.find((s) => pair[1].symbols.includes(s)) ?? -1;
    setMatchSymbol(match);
    setTimer(cfg.timePerRound);
    generateSymbolStyles(pair);
    setPhase('playing');

    if (gameMode === 'online' && mpRef.current.room?.role === 'host') {
      mpRef.current.sendEvent({
        type: 'game-state',
        payload: {
          action: 'start-round',
          pair,
          round: 1,
          matchSymbol: match,
          totalRounds: cfg.totalRounds,
          timePerRound: cfg.timePerRound,
        },
      });
    }
  }, [generateSymbolStyles, gameMode]);

  useEffect(() => {
    if (phase !== 'playing') {
      if (timerRef.current) clearInterval(timerRef.current);
      return;
    }

    timerRef.current = setInterval(() => {
      setTimer((prev) => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          setPhase('gameover');
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [phase]);

  useEffect(() => {
    if (phase === 'gameover') {
      const best = getBest(difficulty);
      if (score > best) {
        saveBest(difficulty, score);
        setIsNewRecord(true);
      }
    }
  }, [phase, difficulty, score]);

  const nextRound = useCallback(() => {
    const nextIdx = roundRef.current + 1;
    roundRef.current = nextIdx;
    roundResolvedRef.current = false;
    const d = deckRef.current;
    const cfg = DIFFICULTY[difficulty];

    if (nextIdx >= cfg.totalRounds || nextIdx * 2 + 1 >= d.length) {
      setPhase('gameover');
      if (gameMode === 'online') {
        mpRef.current.sendEvent({ type: 'game-over', winner: 'draw' });
      }
      return;
    }

    const pair: [CardData, CardData] = [d[nextIdx * 2], d[nextIdx * 2 + 1]];
    setCurrentPair(pair);
    const match = pair[0].symbols.find((s) => pair[1].symbols.includes(s)) ?? -1;
    setMatchSymbol(match);
    setRound(nextIdx + 1);
    setTimer(cfg.timePerRound);
    setWrongId(null);
    setCorrectId(null);
    setHintMsg('');
    setShowPoints(false);
    generateSymbolStyles(pair);
    setPhase('playing');

    if (gameMode === 'online' && mpRef.current.room?.role === 'host') {
      mpRef.current.sendEvent({
        type: 'game-state',
        payload: {
          action: 'start-round',
          pair,
          round: nextIdx + 1,
          matchSymbol: match,
          totalRounds: cfg.totalRounds,
          timePerRound: cfg.timePerRound,
        },
      });
    }
  }, [difficulty, generateSymbolStyles, gameMode]);

  nextRoundRef.current = nextRound;

  const handleSymbolClick = useCallback((symbolIndex: number, cardIndex: number) => {
    if (phase !== 'playing') return;

    if (gameMode === 'online') {
      // In online mode, send the tap to host for resolution
      if (symbolIndex !== matchSymbol) {
        // Wrong — handle locally for instant feedback
        setWrongId(`${cardIndex}-${symbolIndex}`);
        setHintMsg(t('oops', lang));
        setScore((prev) => Math.max(0, prev - 20));
        setTimeout(() => {
          setWrongId(null);
          setHintMsg(t('tapMatch', lang));
        }, 500);
        return;
      }
      // Correct match — if we're host, resolve immediately; if guest, send to host
      if (roundResolvedRef.current) return;
      const role = mpRef.current.room?.role ?? 'guest';
      if (role === 'host') {
        // Host resolves: I (host) got it
        roundResolvedRef.current = true;
        const timeBonus = Math.ceil(timer * 2);
        const points = 100 + timeBonus;
        setScore((prev) => prev + points);
        setCorrectId(`${cardIndex}-${symbolIndex}`);
        setShowPoints(true);
        const cheer = CHEERS[Math.floor(Math.random() * CHEERS.length)];
        setHintMsg(t(cheer, lang));
        setPhase('correct');
        const hostId = mpRef.current.room?.playerId ?? '';
        setPlayerScores((prev) => ({ ...prev, [hostId]: (prev[hostId] ?? 0) + points }));
        mpRef.current.sendEvent({
          type: 'game-state',
          payload: {
            action: 'round-result',
            winnerId: hostId,
            winnerName: mpRef.current.room?.playerName ?? '',
            points,
            correctId: `${cardIndex}-${symbolIndex}`,
          },
        });
        setTimeout(() => { nextRound(); }, 900);
      } else {
        // Guest sends correct tap to host
        mpRef.current.sendEvent({
          type: 'game-state',
          payload: { action: 'guest-spot', symbolIndex, cardIndex, timer, playerId: mpRef.current.room?.playerId },
        });
      }
      return;
    }

    if (symbolIndex === matchSymbol) {
      const timeBonus = Math.ceil(timer * 2);
      const points = 100 + timeBonus;
      setScore((prev) => prev + points);
      setCorrectId(`${cardIndex}-${symbolIndex}`);
      setShowPoints(true);
      const cheer = CHEERS[Math.floor(Math.random() * CHEERS.length)];
      setHintMsg(t(cheer, lang));
      setPhase('correct');

      setTimeout(() => { nextRound(); }, 900);
    } else {
      setWrongId(`${cardIndex}-${symbolIndex}`);
      setHintMsg(t('oops', lang));
      setScore((prev) => Math.max(0, prev - 20));
      setTimeout(() => {
        setWrongId(null);
        setHintMsg(t('tapMatch', lang));
      }, 500);
    }
  }, [phase, matchSymbol, timer, lang, nextRound, gameMode]);

  const symbolSize = useMemo(() => {
    if (difficulty === 'easy') return 80;
    if (difficulty === 'medium') return 64;
    return 52;
  }, [difficulty]);

  const best = getBest(difficulty);

  // ─── Theme Picker ───────────────────────────────────────────────────────────

  if (phase === 'theme') {
    return (
      <Wrapper>
        <MenuWrap>
          <MenuTitle>🃏 {t('title', lang)}</MenuTitle>
          <MenuSubtitle>{t('pickTheme', lang)}</MenuSubtitle>
          <ThemeGrid>
            {THEMES.map((th) => (
              <ThemeCard
                key={th.id}
                accent={th.color}
                onClick={() => { setSymbolTheme(th.id); setPhase('menu'); }}
              >
                <ThemeEmoji>{th.emoji}</ThemeEmoji>
                <ThemeLabel>{t(th.id as keyof typeof T, lang)}</ThemeLabel>
                <ThemePreview>{th.preview.map((e, i) => <span key={i}>{e}</span>)}</ThemePreview>
                <ThemeDesc>{t(`${th.id}Desc` as keyof typeof T, lang)}</ThemeDesc>
              </ThemeCard>
            ))}
          </ThemeGrid>
        </MenuWrap>
      </Wrapper>
    );
  }

  // ─── Difficulty Picker ──────────────────────────────────────────────────────

  if (phase === 'menu') {
    const handleDiffClick = (diff: Difficulty) => {
      if (gameMode === 'online') {
        setDifficulty(diff);
        setPhase('lobby');
      } else {
        startGame(diff);
      }
    };
    return (
      <Wrapper>
        <MenuWrap>
          <MenuTitle>🃏 {t('title', lang)}</MenuTitle>
          <MenuSubtitle>{t('subtitle', lang)}</MenuSubtitle>
          {canOnline && (
            <ModeToggle>
              <ModeToggleBtn active={gameMode === 'solo'} onClick={() => setGameMode('solo')}>🎯 {t('solo', lang)}</ModeToggleBtn>
              <ModeToggleBtn active={gameMode === 'online'} onClick={() => setGameMode('online')}>🌐 {t('online', lang)}</ModeToggleBtn>
            </ModeToggle>
          )}
          <MenuCards>
            <DifficultyCard accent="#3fb950" onClick={() => handleDiffClick('easy')}>
              <DiffEmoji>🌟</DiffEmoji>
              <DiffLabel>{t('easy', lang)}</DiffLabel>
              <DiffDesc>{t('easyDesc', lang)}</DiffDesc>
            </DifficultyCard>
            <DifficultyCard accent="#f59e0b" onClick={() => handleDiffClick('medium')}>
              <DiffEmoji>🔥</DiffEmoji>
              <DiffLabel>{t('medium', lang)}</DiffLabel>
              <DiffDesc>{t('mediumDesc', lang)}</DiffDesc>
            </DifficultyCard>
            <DifficultyCard accent="#f97583" onClick={() => handleDiffClick('hard')}>
              <DiffEmoji>💪</DiffEmoji>
              <DiffLabel>{t('hard', lang)}</DiffLabel>
              <DiffDesc>{t('hardDesc', lang)}</DiffDesc>
            </DifficultyCard>
          </MenuCards>
          {best > 0 && gameMode === 'solo' && (
            <BestBadge>🏆 {t('bestScore', lang)}: {best}</BestBadge>
          )}
        </MenuWrap>
      </Wrapper>
    );
  }

  // ─── Online Lobby ──────────────────────────────────────────────────────────

  if (phase === 'lobby') {
    return (
      <Wrapper>
        <MenuWrap>
          <MenuTitle>🃏 {t('title', lang)}</MenuTitle>
          {!mpHook.room?.connected ? (
            <MultiplayerLobby
              lang={lang}
              room={mpHook.room}
              error={mpHook.error}
              availableRooms={browser.rooms}
              onCreateRoom={() => {
                const { code, roomName } = mpHook.createRoom();
                browser.publishRoom({ code, roomName, hostName: playerName, playerCount: 1 });
              }}
              onJoinRoom={(code) => mpHook.joinRoom(code)}
              onLeaveRoom={() => { browser.unpublishRoom(); mpHook.leaveRoom(); setPhase('menu'); }}
            />
          ) : (
            <>
              <MenuSubtitle>
                {mpHook.room.role === 'host'
                  ? (lang === 'pt' ? `${mpHook.room.players.length} jogadores ligados. Escolhe a dificuldade para começar.` : `${mpHook.room.players.length} players connected. Choose difficulty to start.`)
                  : (lang === 'pt' ? `Ligado! ${mpHook.room.players.length} jogadores na sala. À espera que o anfitrião comece…` : `Connected! ${mpHook.room.players.length} players in room. Waiting for host to start…`)
                }
              </MenuSubtitle>
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', justifyContent: 'center' }}>
                {mpHook.room.players.map((p) => (
                  <span key={p.id} style={{
                    padding: '4px 12px', borderRadius: 12, fontSize: 13, fontWeight: 600,
                    background: p.isHost ? 'rgba(88,166,255,0.12)' : theme.colors.surface,
                    border: `1px solid ${p.isHost ? theme.colors.accent : theme.colors.border}`,
                    color: p.id === mpHook.room?.playerId ? theme.colors.accent : theme.colors.mainText,
                  }}>
                    {p.isHost ? '👑' : '👤'} {p.name}
                  </span>
                ))}
              </div>
              {mpHook.room.role === 'host' && (
                <MenuCards>
                  <DifficultyCard accent="#3fb950" onClick={() => startGame('easy')}>
                    <DiffEmoji>🌟</DiffEmoji>
                    <DiffLabel>{t('easy', lang)}</DiffLabel>
                  </DifficultyCard>
                  <DifficultyCard accent="#f59e0b" onClick={() => startGame('medium')}>
                    <DiffEmoji>🔥</DiffEmoji>
                    <DiffLabel>{t('medium', lang)}</DiffLabel>
                  </DifficultyCard>
                  <DifficultyCard accent="#f97583" onClick={() => startGame('hard')}>
                    <DiffEmoji>💪</DiffEmoji>
                    <DiffLabel>{t('hard', lang)}</DiffLabel>
                  </DifficultyCard>
                </MenuCards>
              )}
            </>
          )}
        </MenuWrap>
      </Wrapper>
    );
  }

  // ─── Game Over ──────────────────────────────────────────────────────────────

  if (phase === 'gameover') {
    const isOnline = gameMode === 'online';
    const iWon = score > opponentScore;
    const isTied = score === opponentScore;
    const onlineTitle = opponentLeftMsg ? t('opponentLeft', lang) : isTied ? t('tied', lang) : iWon ? t('youWin', lang) : t('youLose', lang);

    const handleOnlineRematch = () => {
      if (rematchState === 'received') {
        setRematchState('none');
        setScore(0);
        setOpponentScore(0);
        setPhase('menu');
        mpRef.current.sendEvent({ type: 'rematch-accepted' });
      } else {
        setRematchState('sent');
        mpRef.current.sendEvent({ type: 'rematch-request' });
      }
    };

    return (
      <Wrapper>
        <GameOverWrap>
          <GameOverEmoji>{isOnline ? (iWon ? '🎉' : isTied ? '🤝' : '😅') : '🏆'}</GameOverEmoji>
          <GameOverTitle>{isOnline ? onlineTitle : t('gameOver', lang)}</GameOverTitle>
          <ScoreDisplay>
            {isOnline && (mpHook.room?.players ?? []).length > 2 ? (
              <>
                {(mpHook.room?.players ?? [])
                  .map((p) => ({ ...p, pts: playerScores[p.id] ?? 0 }))
                  .sort((a, b) => b.pts - a.pts)
                  .map((p, i) => (
                    <div key={p.id} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                      <span style={{ fontSize: 16, fontWeight: 700, color: i === 0 ? '#3fb950' : theme.colors.mainTextMuted, minWidth: 20 }}>
                        {i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `${i + 1}.`}
                      </span>
                      <span style={{ color: p.id === mpHook.room?.playerId ? theme.colors.accent : theme.colors.mainText, fontWeight: 600, flex: 1 }}>
                        {p.name}{p.id === mpHook.room?.playerId ? ` (${t('you', lang)})` : ''}
                      </span>
                      <span style={{ fontSize: 20, fontWeight: 800, color: i === 0 ? '#3fb950' : theme.colors.mainText }}>{p.pts}</span>
                    </div>
                  ))}
              </>
            ) : (
              <>
                <ScoreLabel>{isOnline ? t('you', lang) : t('finalScore', lang)}</ScoreLabel>
                <ScoreValue>{score}</ScoreValue>
                {isOnline && (
                  <>
                    <ScoreLabel style={{ marginTop: 8 }}>{t('opponent', lang)}</ScoreLabel>
                    <ScoreValue style={{ color: '#f97583' }}>{opponentScore}</ScoreValue>
                  </>
                )}
              </>
            )}
            <ScoreLabel>{round} {t('rounds', lang)}</ScoreLabel>
          </ScoreDisplay>
          {!isOnline && isNewRecord && <NewRecord>🎉 {t('newRecord', lang)}</NewRecord>}
          {!isOnline && best > 0 && !isNewRecord && (
            <BestBadge>🏆 {t('bestScore', lang)}: {best}</BestBadge>
          )}
          {isOnline && !opponentLeftMsg ? (
            rematchState === 'sent' ? (
              <PlayBtn accent="#666">{t('waiting', lang)}</PlayBtn>
            ) : rematchState === 'received' ? (
              <PlayBtn accent="#3fb950" onClick={handleOnlineRematch}>{t('rematch', lang)} ✓</PlayBtn>
            ) : (
              <PlayBtn accent="#8b5cf6" onClick={handleOnlineRematch}>{t('rematch', lang)}</PlayBtn>
            )
          ) : (
            <PlayBtn accent="#8b5cf6" onClick={() => {
              if (isOnline) mpRef.current.leaveRoom();
              setGameMode('solo');
              setPhase('theme');
            }}>
              {t('playAgain', lang)}
            </PlayBtn>
          )}
        </GameOverWrap>
      </Wrapper>
    );
  }

  // ─── Playing / Correct ──────────────────────────────────────────────────────

  const timerColor = timer <= 3 ? '#f97583' : timer <= 6 ? '#f59e0b' : theme.colors.accent;

  return (
    <Wrapper>
      <GameWrap>
        <TopRow>
          <StatBadge>⭐ {gameMode === 'online' ? t('you', lang) : t('score', lang)}: {score}</StatBadge>
          {gameMode === 'online' && (
            <StatBadge color="#f97583">👤 {t('opponent', lang)}: {opponentScore}</StatBadge>
          )}
          <StatBadge>{t('round', lang)} {round}/{gameMode === 'online' ? configRef.current.totalRounds : config.totalRounds}</StatBadge>
          <StatBadge color={timerColor} urgent={timer <= 3}>
            ⏱️ {timer}s
          </StatBadge>
        </TopRow>

        <Hint wrong={!!wrongId}>
          {hintMsg || t('tapMatch', lang)}
        </Hint>

        {currentPair && (
          <CardsArea>
            {currentPair.map((_, ci) => (
              <>{ci === 1 && <VS>VS</VS>}
              <GameCard key={`card-${ci}-${round}`} highlighted={ci === 0}>
                <CardLabel>{ci === 0 ? 'A' : 'B'}</CardLabel>
                {shuffledSymbols[ci].map((sym) => {
                  const key = `${ci}-${sym}`;
                  const rot = symbolRotations.get(key) ?? 0;
                  const delay = symbolDelays.get(key) ?? 0;
                  const isCorrect = correctId === key;
                  const isWrong = wrongId === key;

                  return (
                    <SymbolBtn
                      key={key}
                      size={symbolSize}
                      rotDeg={rot}
                      correct={isCorrect}
                      wrong={isWrong}
                      style={{ animationDelay: `${delay}s` }}
                      onClick={() => handleSymbolClick(sym, ci)}
                    >
                      {activeSymbols[sym % activeSymbols.length]}
                      {isCorrect && (
                        <>
                          <Sparkle x={10} y={10} delay={0}>✨</Sparkle>
                          <Sparkle x={80} y={20} delay={0.1}>✨</Sparkle>
                          <Sparkle x={20} y={80} delay={0.15}>✨</Sparkle>
                          <Sparkle x={75} y={75} delay={0.2}>✨</Sparkle>
                        </>
                      )}
                    </SymbolBtn>
                  );
                })}
                {showPoints && ci === 0 && (
                  <PointsFloat>+{100 + Math.ceil(timer * 2)}</PointsFloat>
                )}
              </GameCard>
              </>
            ))}
          </CardsArea>
        )}

        {phase === 'correct' && (
          <FeedbackOverlay>
            <FeedbackEmoji>🎉</FeedbackEmoji>
            <FeedbackText color="#3fb950">{hintMsg}</FeedbackText>
            {CONFETTI_COLORS.map((c, i) => (
              <Confetti key={i} left={10 + i * 15} delay={i * 0.08} color={c}>{['🎊', '⭐', '🌟', '💫', '✨', '🎉'][i]}</Confetti>
            ))}
          </FeedbackOverlay>
        )}
      </GameWrap>
    </Wrapper>
  );
}
