type LobbyPhase = 'idle' | 'hosting' | 'joining';

export function MultiplayerLobby({
  lang,
  room,
  error,
  onCreateRoom,
  onJoinRoom,
  onLeaveRoom,
  availableRooms = [],
}: MultiplayerLobbyProps) {
  const [phase, setPhase] = useState<LobbyPhase>('idle');
  const [name, setName] = useState(() => loadPlayerName());
  const [joinCode, setJoinCode] = useState('');
  const [copied, setCopied] = useState(false);
  const codeInputRef = useRef<HTMLInputElement>(null);

  const handleCreateRoom = () => {
    if (!name.trim()) return;
    savePlayerName(name.trim());
    setPhase('hosting');
    onCreateRoom(name.trim());
  };

  const handleStartJoin = () => {
    if (!name.trim()) return;
    savePlayerName(name.trim());
    setPhase('joining');
    setTimeout(() => codeInputRef.current?.focus(), 100);
  };

  const handleJoin = () => {
    const code = joinCode.trim().toUpperCase();
    if (code.length < 4) return;
    onJoinRoom(code, name.trim());
  };

  const handleCopy = () => {
    if (!room) return;
    navigator.clipboard.writeText(room.code).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  const handleLeave = () => {
    setPhase('idle');
    setJoinCode('');
    onLeaveRoom();
  };

  if (room?.connected) {
    return null;
  }

  if (phase === 'hosting' && room) {
    const players = room.players ?? [];
    return (
      <Wrapper>
        {room.roomName && (
          <Title style={{ fontSize: 18, color: theme.colors.accent }}>{room.roomName}</Title>
        )}
        <Title>🌐 {t('shareCode', lang)}</Title>
        <CodeDisplay>
          <Code>{room.code}</Code>
          <CopyBtn onClick={handleCopy}>
            {copied ? t('copied', lang) : t('copy', lang)}
          </CopyBtn>
        </CodeDisplay>
        {players.length > 1 && (
          <PlayerList>
            <PlayerListLabel>{t('players', lang)} ({players.length})</PlayerListLabel>
            {players.map((p) => (
              <PlayerRow key={p.id}>
                {p.isHost ? '👑' : '👤'} {p.name}
                {p.isHost && <HostBadge>Host</HostBadge>}
              </PlayerRow>
            ))}
          </PlayerList>
        )}
        {players.length <= 1 && <WaitingText>{t('waiting', lang)}</WaitingText>}
        {error && <ErrorText>{error}</ErrorText>}
        <Button variant="secondary" onClick={handleLeave}>
          {t('leave', lang)}
        </Button>
      </Wrapper>
    );
  }

  if (phase === 'joining') {
    return (
      <Wrapper>
        <Title>🔗 {t('joinRoom', lang)}</Title>
        <Section>
          <Label>{t('enterCode', lang)}</Label>
          <CodeInput
            ref={codeInputRef}
            value={joinCode}
            onChange={(e) => setJoinCode(e.target.value.toUpperCase().slice(0, 6))}
            placeholder="ABC123"
            maxLength={6}
            onKeyDown={(e) => e.key === 'Enter' && handleJoin()}
          />
        </Section>
        {error && <ErrorText>{error}</ErrorText>}
        <ButtonRow>
          <Button variant="secondary" onClick={handleLeave}>
            {t('leave', lang)}
          </Button>
          <Button
            variant="primary"
            onClick={handleJoin}
            disabled={joinCode.trim().length < 4}
          >
            {t('join', lang)}
          </Button>
        </ButtonRow>
      </Wrapper>
    );
  }

  const handleJoinRoom = (code: string) => {
    if (!name.trim()) return;
    savePlayerName(name.trim());
    onJoinRoom(code, name.trim());
  };

  return (
    <Wrapper>
      <Title>🌐 {t('playOnline', lang)}</Title>
      <Section>
        <Label>{t('yourName', lang)}</Label>
        <Input
          value={name}
          onChange={(e) => setName(e.target.value.slice(0, 20))}
          placeholder={t('namePlaceholder', lang)}
          onKeyDown={(e) => e.key === 'Enter' && handleCreateRoom()}
        />
      </Section>
      {error && <ErrorText>{error}</ErrorText>}

      {availableRooms.length > 0 && (
        <RoomList>
          <RoomListHeader>
            <RoomListTitle>{t('openRooms', lang)} ({availableRooms.length})</RoomListTitle>
          </RoomListHeader>
          {availableRooms.map((r) => (
            <RoomCard
              key={r.code}
              onClick={() => handleJoinRoom(r.code)}
              disabled={!name.trim()}
            >
              <RoomCardInfo>
                <RoomCardName>{r.roomName || r.code}</RoomCardName>
                <RoomCardMeta>👑 {r.hostName}</RoomCardMeta>
              </RoomCardInfo>
              <RoomCardPlayers>👤 {r.playerCount}</RoomCardPlayers>
            </RoomCard>
          ))}
        </RoomList>
      )}

      {availableRooms.length === 0 && (
        <NoRoomsText>{t('noRooms', lang)}</NoRoomsText>
      )}

      <ButtonRow>
        <Button
          variant="primary"
          onClick={handleCreateRoom}
          disabled={!name.trim()}
        >
          {t('createRoom', lang)}
        </Button>
      </ButtonRow>
      <Divider>{t('or', lang)}</Divider>
      <ButtonRow>
        <Button
          variant="secondary"
          onClick={handleStartJoin}
          disabled={!name.trim()}
        >
          {t('joinDirect', lang)}
        </Button>
      </ButtonRow>
    </Wrapper>
  );
}
